# ==============================================================================
#  ONE-SHOT-UPLOAD-INTERNATIONAL-SOUPS.ps1
#  Nigel A. Thomas - nigelthomas.live
#
#  RUN FROM THE REPO ROOT:
#    PS C:\Users\admin\Desktop\nigelthomas-portfolio> .\ONE-SHOT-UPLOAD-INTERNATIONAL-SOUPS.ps1
#
#  If Windows blocks the script:
#    powershell -ExecutionPolicy Bypass -File .\ONE-SHOT-UPLOAD-INTERNATIONAL-SOUPS.ps1
#
#  Build only (no git pull/commit/push):  add  -NoPush
#
#  WHAT IT DOES
#    1. git pull --rebase --autostash (so blog.html / sitemap.xml are current)
#    2. Decodes the embedded poster (bottom of this file) -> assets\international-soups-poster.jpg
#    3. Writes international-soups.html  (black/gold design, VIEW INFOMATICS toggle,
#       download-poster button, 3 related blog links)
#    4. Adds the blog card to blog.html (after the last END NEW CARD marker)
#    5. Adds page URL + poster (image) URL to sitemap.xml
#    6. Commits only these 4 files, pushes, then checks the live URLs for 200 OK
#
#  All files are written as UTF-8 WITHOUT BOM. This script is pure ASCII on purpose.
# ==============================================================================
param([switch]$NoPush)
$ErrorActionPreference = 'Stop'

function Write-Utf8NoBom([string]$Path, [string]$Text) {
    $enc = New-Object System.Text.UTF8Encoding $false
    [System.IO.File]::WriteAllText($Path, $Text, $enc)
}
function Read-Utf8([string]$Path) {
    $enc = New-Object System.Text.UTF8Encoding $false
    return [System.IO.File]::ReadAllText($Path, $enc)
}
function Invoke-Git([string[]]$GitArgs) {
    $old = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        & git $GitArgs 2>&1 | ForEach-Object { Write-Host ("    " + [string]$_) -ForegroundColor Gray }
    } finally {
        $ErrorActionPreference = $old
    }
    return $LASTEXITCODE
}

function Invoke-Main {
    $root      = (Get-Location).Path
    $slug      = 'international-soups'
    $base      = 'https://www.nigelthomas.live'
    $pageFile  = Join-Path $root ($slug + '.html')
    $assetsDir = Join-Path $root 'assets'
    $posterFile= Join-Path $assetsDir ($slug + '-poster.jpg')
    $blogFile  = Join-Path $root 'blog.html'
    $siteFile  = Join-Path $root 'sitemap.xml'
    $today     = Get-Date -Format 'yyyy-MM-dd'

    Write-Host ''
    Write-Host '=== INTERNATIONAL SOUPS - ONE-SHOT BUILD ===' -ForegroundColor Yellow
    Write-Host ('Repo: ' + $root) -ForegroundColor Gray

    if (-not (Test-Path $blogFile)) { throw 'blog.html not found. Run this script from the repo root (nigelthomas-portfolio).' }
    if (-not (Test-Path $siteFile)) { throw 'sitemap.xml not found. Run this script from the repo root (nigelthomas-portfolio).' }

    $hasGit = (Test-Path (Join-Path $root '.git')) -and [bool](Get-Command git -ErrorAction SilentlyContinue)
    if (-not $NoPush -and -not $hasGit) { throw 'git not available or this is not a git repo. Re-run with -NoPush.' }

    # ---- 1. pull ----------------------------------------------------------
    if (-not $NoPush) {
        Write-Host '[1/6] git pull --rebase --autostash' -ForegroundColor Cyan
        $rc = Invoke-Git @('pull', '--rebase', '--autostash')
        if ($rc -ne 0) { throw 'git pull --rebase failed. Fix the git state, then re-run.' }
    } else {
        Write-Host '[1/6] skipped git pull (-NoPush)' -ForegroundColor Gray
    }

    # ---- 2. poster --------------------------------------------------------
    Write-Host '[2/6] Writing poster' -ForegroundColor Cyan
    if (-not (Test-Path $assetsDir)) { New-Item -ItemType Directory -Path $assetsDir | Out-Null }
    $b64   = ($script:PosterB64 -replace '\s', '')
    $bytes = [Convert]::FromBase64String($b64)
    if ($bytes.Length -lt 10000 -or $bytes[0] -ne 0xFF -or $bytes[1] -ne 0xD8) { throw 'Embedded poster is corrupt (not a JPEG). Re-download the script.' }
    [System.IO.File]::WriteAllBytes($posterFile, $bytes)
    Write-Host ('    assets\' + $slug + '-poster.jpg  (' + [math]::Round($bytes.Length / 1KB) + ' KB)') -ForegroundColor Green

    # ---- 3. page ----------------------------------------------------------
    Write-Host '[3/6] Writing international-soups.html' -ForegroundColor Cyan
    $page = @'
