'@
    Write-Utf8NoBom $pageFile $page
    Write-Host ('    ' + $slug + '.html  (' + [math]::Round((Get-Item $pageFile).Length / 1KB) + ' KB)') -ForegroundColor Green

    # ---- 4. blog.html card -----------------------------------------------
    Write-Host '[4/6] Updating blog.html' -ForegroundColor Cyan
    $blog = Read-Utf8 $blogFile
    $nl   = "`n"
    if ($blog.Contains("`r`n")) { $nl = "`r`n" }
    if ($blog -match 'international-soups\.html') {
        Write-Host '    blog.html already contains the card - skipped' -ForegroundColor Yellow
    } else {
        $tag = 'div'
        if ($blog -match '<(\w+)[^>]*class="[^"]*\barticle-card\b') { $tag = $Matches[1] }
        $maxN = 0
        $rx = New-Object System.Text.RegularExpressions.Regex('<!--\s*END NEW CARD\s*(\d+)?\s*-->')
        $ms = $rx.Matches($blog)
        foreach ($m in $ms) { if ($m.Groups[1].Success) { $v = [int]$m.Groups[1].Value; if ($v -gt $maxN) { $maxN = $v } } }
        $cardNo = $maxN + 1
        $cardLines = @(
            ('<' + $tag + ' class="article-card">'),
            '    <img src="assets/international-soups-poster.jpg" alt="International Soups - 12 Famous Soups From Around the World" loading="lazy"/>',
            '    <h3 class="article-title">International Soups: 12 Famous Soups From Around the World</h3>',
            '    <div class="article-meta">Food &amp; Beverage | September 2026</div>',
            '    <p class="article-excerpt">French Onion, Minestrone, Miso, Tom Yum, Gazpacho, Borscht, Pho and more - 12 famous soups with service, allergen and food safety notes, plus a free downloadable poster.</p>',
            '    <a href="international-soups.html" class="read-more-btn">Read More</a>',
            ('</' + $tag + '>')
        )
        $card = ($cardLines -join $nl)
        if ($ms.Count -gt 0) {
            $last = $ms[$ms.Count - 1]
            $pos  = $last.Index + $last.Length
            $ins  = $nl + $nl + $card + $nl + ('<!-- END NEW CARD ' + $cardNo + ' -->')
            $blog = $blog.Insert($pos, $ins)
            Write-Utf8NoBom $blogFile $blog
            Write-Host ('    Card added as NEW CARD ' + $cardNo + ' (after the last END NEW CARD marker)') -ForegroundColor Green
        } else {
            Write-Host '    No END NEW CARD marker found - paste this card into blog.html yourself:' -ForegroundColor Yellow
            Write-Host $card -ForegroundColor White
        }
    }

    # ---- 5. sitemap.xml ---------------------------------------------------
    Write-Host '[5/6] Updating sitemap.xml' -ForegroundColor Cyan
    $site = Read-Utf8 $siteFile
    $snl  = "`n"
    if ($site.Contains("`r`n")) { $snl = "`r`n" }
    if ($site -match 'international-soups\.html') {
        Write-Host '    sitemap.xml already contains the URL - skipped' -ForegroundColor Yellow
    } else {
        if ($site -notmatch 'xmlns:image') {
            $site = [regex]::Replace($site, '<urlset\b', '<urlset xmlns:image="http://www.google.com/schemas/sitemap-image/1.1"', 1)
        }
        $entryLines = @(
            '  <url>',
            ('    <loc>' + $base + '/international-soups.html</loc>'),
            ('    <lastmod>' + $today + '</lastmod>'),
            '    <changefreq>monthly</changefreq>',
            '    <priority>0.8</priority>',
            '    <image:image>',
            ('      <image:loc>' + $base + '/assets/international-soups-poster.jpg</image:loc>'),
            '    </image:image>',
            '  </url>'
        )
        $entry = ($entryLines -join $snl) + $snl
        $idx = $site.LastIndexOf('</urlset>')
        if ($idx -lt 0) { throw 'No </urlset> found in sitemap.xml' }
        $site = $site.Insert($idx, $entry)
        $xml = New-Object System.Xml.XmlDocument
        try { $xml.LoadXml($site) } catch { throw ('sitemap.xml would be invalid XML - nothing written. ' + $_.Exception.Message) }
        Write-Utf8NoBom $siteFile $site
        Write-Host '    Page URL + poster URL added, XML validated' -ForegroundColor Green
    }

    # ---- 6. commit / push / verify ---------------------------------------
    if ($NoPush) {
        Write-Host '[6/6] -NoPush set: files written locally, nothing committed.' -ForegroundColor Yellow
        Write-Host '      Review with: git diff --stat' -ForegroundColor Gray
        return
    }
    Write-Host '[6/6] Commit, push, verify' -ForegroundColor Cyan
    $rc = Invoke-Git @('add', '--', 'international-soups.html', 'assets/international-soups-poster.jpg', 'blog.html', 'sitemap.xml')
    if ($rc -ne 0) { throw 'git add failed' }
    $pending = & git status --porcelain -- international-soups.html assets/international-soups-poster.jpg blog.html sitemap.xml
    if ($pending) {
        $rc = Invoke-Git @('commit', '-m', 'Add International Soups poster page, blog card and sitemap entries')
        if ($rc -ne 0) { throw 'git commit failed' }
    } else {
        Write-Host '    Nothing new to commit' -ForegroundColor Yellow
    }
    $rc = Invoke-Git @('push')
    if ($rc -ne 0) {
        Write-Host '    push rejected - retrying after pull --rebase --autostash' -ForegroundColor Yellow
        $rc = Invoke-Git @('pull', '--rebase', '--autostash')
        if ($rc -eq 0) { $rc = Invoke-Git @('push') }
        if ($rc -ne 0) { throw 'git push failed. Resolve manually.' }
    }

    Write-Host ''
    Write-Host 'Waiting for Vercel and checking live URLs (GET, 200 + content match)...' -ForegroundColor Cyan
    $stamp = Get-Date -Format 'yyyyMMddHHmmss'
    $targets = @(
        @{ Url = ($base + '/international-soups.html');                  Must = 'International Soups' },
        @{ Url = ($base + '/assets/international-soups-poster.jpg');     Must = '' },
        @{ Url = ($base + '/blog.html');                                 Must = 'international-soups.html' },
        @{ Url = ($base + '/sitemap.xml');                               Must = 'international-soups.html' }
    )
    $left = $targets
    for ($i = 1; $i -le 18 -and $left.Count -gt 0; $i++) {
        $still = @()
        foreach ($t in $left) {
            $ok = $false
            try {
                $r = Invoke-WebRequest -Uri ($t.Url + '?v=' + $stamp) -UseBasicParsing -TimeoutSec 30
                if ($r.StatusCode -eq 200) {
                    if ($t.Must -eq '') { $ok = $true } else { $ok = ([string]$r.Content).Contains($t.Must) }
                }
            } catch { $ok = $false }
            if ($ok) { Write-Host ('    [200 OK] ' + $t.Url) -ForegroundColor Green } else { $still += $t }
        }
        $left = $still
        if ($left.Count -gt 0 -and $i -lt 18) {
            Write-Host ('    ...still deploying (' + $left.Count + ' pending), retry in 10s') -ForegroundColor Gray
            Start-Sleep -Seconds 10
        }
    }
    if ($left.Count -gt 0) {
        Write-Host 'NOT CONFIRMED LIVE YET:' -ForegroundColor Red
        foreach ($t in $left) { Write-Host ('    ' + $t.Url) -ForegroundColor Red }
        Write-Host 'Check the Vercel dashboard, then re-run the URL checks.' -ForegroundColor Yellow
    }

    Write-Host ''
    Write-Host '=== GOOGLE SEARCH CONSOLE ===' -ForegroundColor Yellow
    Write-Host 'URL Inspection -> Request Indexing for:' -ForegroundColor White
    Write-Host ('   PAGE  : ' + $base + '/international-soups.html') -ForegroundColor White
    Write-Host ('   POSTER: ' + $base + '/assets/international-soups-poster.jpg') -ForegroundColor White
    Write-Host ('Sitemaps -> resubmit: ' + $base + '/sitemap.xml') -ForegroundColor White
    Write-Host ''
    Write-Host 'DONE.' -ForegroundColor Green
}

